CREATE TABLE IF NOT EXISTS config_revisions(scope TEXT PRIMARY KEY, revision BIGINT NOT NULL DEFAULT 0 CHECK (revision >= 0));
CREATE TABLE IF NOT EXISTS system_settings(id SMALLINT PRIMARY KEY CHECK (id = 1), default_concurrency INTEGER NOT NULL DEFAULT 8, request_timeout_ms INTEGER NOT NULL DEFAULT 15000, cache_ttl_minutes INTEGER NOT NULL DEFAULT 5, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS search_settings(id SMALLINT PRIMARY KEY CHECK (id = 1), concurrency INTEGER, sources_configured BOOLEAN NOT NULL DEFAULT false, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS search_setting_sources(source_id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS resource_sources(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', url TEXT NOT NULL, method TEXT NOT NULL CHECK(method IN ('GET','POST')), format TEXT NOT NULL CHECK(format IN ('json','html','text')), priority INTEGER NOT NULL DEFAULT 0, enabled BOOLEAN NOT NULL DEFAULT true, request_json JSONB, transform TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_resource_sources_enabled ON resource_sources(enabled, priority, id);
CREATE TABLE IF NOT EXISTS source_template_settings(id SMALLINT PRIMARY KEY CHECK(id = 1), url_template TEXT NOT NULL, method TEXT NOT NULL, format TEXT NOT NULL, request_json JSONB, transform TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hot_searches(term TEXT PRIMARY KEY, normalized_term TEXT NOT NULL DEFAULT '', score BIGINT NOT NULL DEFAULT 0, last_searched TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), status TEXT NOT NULL DEFAULT 'approved', source TEXT NOT NULL DEFAULT 'auto', pinned BOOLEAN NOT NULL DEFAULT false, manual_weight INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_hot_searches_rank ON hot_searches(score DESC, last_searched DESC);
CREATE TABLE IF NOT EXISTS source_health(source_id TEXT PRIMARY KEY, snapshot_json JSONB NOT NULL DEFAULT '{}'::jsonb, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS proxy_nodes(id TEXT PRIMARY KEY, name TEXT NOT NULL, base_url TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true, daily_limit INTEGER NOT NULL DEFAULT 0, quota_day DATE, quota_used INTEGER NOT NULL DEFAULT 0, circuit_state TEXT NOT NULL DEFAULT 'closed', failure_count INTEGER NOT NULL DEFAULT 0, probe_in_flight BOOLEAN NOT NULL DEFAULT false, opened_until TIMESTAMPTZ, last_status INTEGER, last_error TEXT, last_success_at TIMESTAMPTZ, last_failure_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS proxy_groups(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', enabled BOOLEAN NOT NULL DEFAULT true, fallback_action TEXT NOT NULL DEFAULT 'error', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS proxy_group_nodes(group_id TEXT NOT NULL REFERENCES proxy_groups(id) ON DELETE CASCADE, node_id TEXT NOT NULL REFERENCES proxy_nodes(id) ON DELETE CASCADE, weight INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(group_id,node_id));
CREATE TABLE IF NOT EXISTS proxy_routes(id TEXT PRIMARY KEY, name TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 100, enabled BOOLEAN NOT NULL DEFAULT true, source_ids_json JSONB NOT NULL DEFAULT '[]'::jsonb, action TEXT NOT NULL, group_id TEXT REFERENCES proxy_groups(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS managed_resources(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, datetime TEXT, cloud_types_json JSONB NOT NULL DEFAULT '[]'::jsonb, links_json JSONB NOT NULL DEFAULT '[]'::jsonb, tags_json JSONB NOT NULL DEFAULT '[]'::jsonb, images_json JSONB NOT NULL DEFAULT '[]'::jsonb, search_text TEXT NOT NULL DEFAULT '', enabled BOOLEAN NOT NULL DEFAULT true, check_status TEXT NOT NULL DEFAULT 'unchecked', check_message TEXT, checked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_managed_resources_updated_at ON managed_resources(updated_at DESC);
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY, username TEXT NOT NULL, username_normalized TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, nickname TEXT, role TEXT NOT NULL DEFAULT 'user', status TEXT NOT NULL DEFAULT 'active', custom_channels_json JSONB NOT NULL DEFAULT '[]'::jsonb, custom_channels_updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_login_ip TEXT, last_login_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_users_created_at ON users(created_at DESC);
CREATE TABLE IF NOT EXISTS auth_identities(provider TEXT NOT NULL, provider_app_id TEXT NOT NULL, subject TEXT NOT NULL, provider_union_id TEXT, user_id BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(provider,provider_app_id,subject), UNIQUE(provider,provider_app_id,user_id));
CREATE TABLE IF NOT EXISTS wechat_mini_settings(id SMALLINT PRIMARY KEY CHECK(id=1), app_id TEXT NOT NULL DEFAULT '', secret TEXT NOT NULL DEFAULT '', qr_page TEXT NOT NULL DEFAULT 'pages/login/index', env_version TEXT NOT NULL DEFAULT 'release', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cloud_account_settings(provider TEXT PRIMARY KEY, credential TEXT NOT NULL DEFAULT '', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS search_logs(id BIGSERIAL PRIMARY KEY, session_id TEXT, user_id BIGINT REFERENCES users(id) ON DELETE SET NULL, keyword TEXT NOT NULL, ip TEXT NOT NULL, search_scope TEXT NOT NULL, channels_json JSONB NOT NULL DEFAULT '[]'::jsonb, source_ids_json JSONB NOT NULL DEFAULT '[]'::jsonb, status TEXT NOT NULL DEFAULT 'started', result_count INTEGER NOT NULL DEFAULT 0, has_results BOOLEAN NOT NULL DEFAULT false, source_result_counts_json JSONB NOT NULL DEFAULT '{}'::jsonb, completed_at TIMESTAMPTZ, outcome_recorded BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_search_logs_created_at ON search_logs(created_at DESC);
CREATE TABLE IF NOT EXISTS policy_settings(key TEXT PRIMARY KEY, value_json JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
